<?php elseif($trackingId!==''):?><form method="post" class="checkout-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="tracking-verify"><label><?=tr('Phone verification code','ফোন যাচাই কোড')?><input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><button class="btn"><?=tr('Verify and track','যাচাই করে ট্র্যাক করুন')?></button></form><?php endif;?>
